import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Config profile, quote, limiti e audit","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/profili-quote-audit.md","filePath":"admin-guide/profili-quote-audit.md"}'),d={name:"admin-guide/profili-quote-audit.md"};function n(r,e,l,c,s,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="config-profile-quote-limiti-e-audit" tabindex="-1">Config profile, quote, limiti e audit <a class="header-anchor" href="#config-profile-quote-limiti-e-audit" aria-label="Permalink to &quot;Config profile, quote, limiti e audit&quot;">​</a></h1><p>Tutte le funzioni di questa pagina stanno nella <strong>console di amministrazione</strong> della Web UI (visibile agli utenti con ruolo <code>clarae-admin</code>).</p><h2 id="gruppi" tabindex="-1">Gruppi <a class="header-anchor" href="#gruppi" aria-label="Permalink to &quot;Gruppi&quot;">​</a></h2><p>Un gruppo è un insieme di utenti usato per <strong>condividere</strong> cartelle/vault e per <strong>assegnare config profile</strong>. Si gestiscono in <em>Amministrazione → Gruppi</em> (crea, rinomina, aggiungi/rimuovi membri). Eliminare un gruppo elimina anche le sue condivisioni e le assegnazioni dei profili. I gruppi esistono solo nel database di Clarae notanda (non in Keycloak).</p><h2 id="config-profile" tabindex="-1">Config profile <a class="header-anchor" href="#config-profile" aria-label="Permalink to &quot;Config profile&quot;">​</a></h2><p>Un profilo è un JSON <strong>versionato</strong> che l&#39;amministratore distribuisce ai client desktop; serve anche da feature flag. Ordine di risoluzione, dal meno al più prioritario:</p><ol><li>valori predefiniti del prodotto;</li><li>profilo <strong>globale</strong>;</li><li>profili dei <strong>gruppi</strong> dell&#39;utente, in ordine di priorità (si imposta nella pagina del gruppo);</li><li>impostazioni dell&#39;utente, <strong>tranne</strong> le chiavi bloccate (<code>locked_keys</code>).</li></ol><p>Le chiavi di primo livello ammesse sono quelle dello schema (<code>editor</code>, <code>appearance</code>, <code>hotkeys</code>, <code>features</code>, …); l&#39;editor segnala chiavi sconosciute, JSON non valido e chiavi bloccate non valide. Sul client le impostazioni bloccate appaiono disabilitate con &quot;gestito dall&#39;amministratore&quot;. Ogni salvataggio crea una nuova versione (storico con possibilità di <strong>ripristino</strong>) e i client si aggiornano via notifica. Esempi di uso come feature flag: <code>features.sharing = false</code>, <code>features.drawings = false</code>.</p><p>La pagina di un utente mostra la <strong>configurazione effettiva</strong> risolta (con le chiavi bloccate), utile per capire perché un client si comporta in un certo modo.</p><h3 id="chiavi-del-profilo" tabindex="-1">Chiavi del profilo <a class="header-anchor" href="#chiavi-del-profilo" aria-label="Permalink to &quot;Chiavi del profilo&quot;">​</a></h3><p>Lo schema <code>api/config-profile.schema.json</code> è l&#39;unica fonte delle chiavi, dei tipi e dei default: <code>task gen</code> ne genera le costanti Go (<code>shared/go/features</code>) e TypeScript (<code>@clarae/api-client/features</code>) e i default del prodotto distribuiti dal cloud. Un test (<code>shared/go/features</code>, <code>go test ./features/...</code>) confronta questa tabella con lo schema: una chiave nuova senza riga, o con tipo o default diversi, lo fa fallire.</p><p><em>Bloccabile</em> indica se <code>locked_keys</code> ha effetto, cioè se esiste una scelta dell&#39;utente che il blocco sostituisce (per le altre chiavi il valore del profilo vale sempre). <em>Default</em> è il valore del prodotto; «—» vuol dire che senza profilo vale l&#39;impostazione dell&#39;utente o quella predefinita dell&#39;app. Un flag <code>features.*</code> non elencato è accettato e ignorato dai client che non lo conoscono.</p><table tabindex="0"><thead><tr><th>Chiave</th><th>Tipo</th><th>Default</th><th>Effetto</th><th>Bloccabile</th><th>Client</th></tr></thead><tbody><tr><td><code>features.audio_recorder</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Registratore audio nell&#39;editor. Riservato: nessun client offre ancora la funzione, il flag non ha effetti visibili.</td><td>no</td><td>—</td></tr><tr><td><code>features.web_viewer</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Applicazioni: una pagina web registrata nel vault (file <code>.webapp</code>) si apre in un browser incorporato in una scheda. Acceso di default dalla 1.7.2 (ADR-0060). Spento da un profilo, <em>Nuova applicazione</em> non compare e <em>Apri applicazione…</em>, <em>Cambia indirizzo</em> ed <em>Elimina i dati delle applicazioni</em> non sono disponibili; un <code>.webapp</code> già presente si apre come riquadro con «Apri nel browser». Il browser incorporato c&#39;è <strong>sul client desktop per macOS, Windows e Linux</strong> (ADR-0062, accettata; Windows e Linux provati su una finestra reale dall&#39;owner il 27 novembre 2026, con esito positivo dichiarato); nel workbench web, e sui computer dove il runtime manca o la vista è spenta con <code>CLARAE_WEBVIEW=off</code>, il flag abilita creazione e apertura, ma la pagina si apre nel browser di sistema o in una nuova scheda del browser. Spegnerlo chiude le pagine aperte ma <strong>non cancella</strong> i dati di sessione già salvati sui dispositivi. Vedi <a href="#applicazioni-note-per-chi-amministra">Applicazioni: note per chi amministra</a></td><td>no</td><td>desktop (browser incorporato su macOS, Windows e Linux), workbench web (scheda del browser)</td></tr><tr><td><code>features.presence</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Presenza in tempo reale sui vault <strong>condivisi</strong>: gli avatar degli altri utenti che hanno aperto lo stesso documento e i loro cursori. I vault privati non ne hanno. Spento, il client non apre la connessione di presenza e il cloud la rifiuta (<code>presence-disabled</code>). Niente viene salvato né finisce nell&#39;audit</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.chat</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Barra della chat del workbench (segnaposto disabilitato finché non c&#39;è l&#39;integrazione ACP, ADR-0026).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.ai</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Riservato e spento (ADR-0050): assistente di scrittura AI dell&#39;editor, implementato ma inattivo. Un profilo non può accenderlo: serve una build dedicata che lo abiliti, quindi in una build rilasciata <code>true</code> non cambia nulla.</td><td>no</td><td>—</td></tr><tr><td><code>features.collab</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Riservato e spento (ADR-0050): collaborazione in tempo reale nell&#39;editor, implementata ma spenta. Un profilo non può accenderla: servono una build dedicata e un provider registrato, che oggi non esiste; in una build rilasciata <code>true</code> non cambia nulla.</td><td>no</td><td>—</td></tr><tr><td><code>features.web_workbench</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Apertura dei vault nel browser (workbench web, ADR-0029): spento, la console nasconde «Apri» e il workbench rifiuta anche un indirizzo digitato. Il desktop lo ignora.</td><td>no</td><td>console web, workbench web</td></tr><tr><td><code>features.drawings</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Disegni Excalidraw: creazione, apertura e incorporamento dei file <code>.excalidraw</code>. Spento, spegne anche tutti i <code>drawing_*</code>.</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.canvas</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Canvas (<code>.canvas</code>): creazione e apertura.</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.presentations</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Presentazioni Marp (<code>.marp</code>): creazione, pannello SlideShow, presentazione a tutto schermo ed export HTML, PDF e PPTX (ADR-0047, ADR-0048).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.sharing</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Condivisione di un vault con utenti e gruppi e condivisioni ricevute: sezione delle impostazioni, barra di stato e menu dei file del workbench; pagina Condivisioni, mount e inviti della console.</td><td>no</td><td>desktop, workbench web, console web</td></tr><tr><td><code>features.drawing_latex</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Formule LaTeX nei disegni (solo con <code>drawings</code> acceso).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.drawing_mermaid</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Diagrammi Mermaid convertiti in disegno (solo con <code>drawings</code> acceso).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.drawing_auto_export</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Esportazione automatica SVG/PNG dei disegni al salvataggio (solo con <code>drawings</code> acceso).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.drawing_actions</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Azioni sulla scena del pannello strumenti dei disegni (solo con <code>drawings</code> acceso).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.envelope_v2</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Envelope delle chiavi dei vault privati in formato v2, legato a vault e tipo (ADR-0034), e upgrade a v2 allo sblocco. Spento: niente nuovi upgrade, ma un tipo già v2 resta v2. I desktop fino alla 1.2.4 non aprono un v2 (vedi <code>backup-upgrade.md</code>).</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.path_v2</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Token dei path dei vault privati in formato <code>enc2</code>, legato al file (ADR-0042), e migrazione in background dei token <code>enc1</code>. Spento: niente migrazione, ma un vault già <code>enc2</code> resta <code>enc2</code>. I desktop fino alla 1.2.4 non leggono <code>enc2</code>.</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>features.config_dir_v2</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Sposta le impostazioni sincronizzate dei vault collegati (editor, scorciatoie, aspetto, template, …) dalla vecchia cartella di configurazione alla nuova (ADR-0052), come un normale spostamento di file che conserva id e storico, un file alla volta a fine ciclo di sincronizzazione. Acceso per default dalla 1.7.0, ma solo dopo che il client ha letto un profilo del server (fresco o in cache): prima non sposta nulla. I client 1.4 e precedenti leggono e scrivono ancora la vecchia cartella e, se la trovassero vuota, ricreerebbero ogni impostazione: <strong>aggiornare ogni dispositivo di ogni vault collegato prima di portare il cloud alla 1.7, oppure impostare <code>false</code> nel profilo finché non lo sono.</strong> Spegnere ferma solo lo spostamento: quelli già fatti restano e il client legge entrambe le cartelle. Un cloud 1.5 o 1.6 distribuisce <code>false</code>, uno 1.7 <code>true</code>. Vedi <a href="./migrazione-clarae.html">migrazione-clarae.md</a>.</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>editor.fontSize</code></td><td><code>integer</code></td><td>—</td><td>Dimensione del carattere dell&#39;editor (8–48).</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.lineWrap</code></td><td><code>boolean</code></td><td>—</td><td>A capo automatico delle righe.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.readableWidth</code></td><td><code>boolean</code></td><td>—</td><td>Larghezza di lettura limitata.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.spellcheck</code></td><td><code>boolean</code></td><td>—</td><td>Controllo ortografico.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.newNoteFolder</code></td><td><code>string</code></td><td>—</td><td>Cartella delle nuove note.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.attachmentsFolder</code></td><td><code>string</code></td><td>—</td><td>Cartella degli allegati.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.linkFormat</code></td><td>enum: <code>shortest</code>, <code>path</code>, <code>relative</code></td><td>—</td><td>Formato dei link creati dall&#39;app.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>editor.smartPaste</code></td><td><code>boolean</code></td><td>—</td><td>Incolla intelligente (URL su testo selezionato diventa link).</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>appearance.theme</code></td><td>enum: <code>system</code>, <code>light</code>, <code>dark</code></td><td>—</td><td>Tema. Il blocco disabilita il controllo, ma oggi nessun client applica il valore del profilo.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>appearance.accent</code></td><td><code>string</code></td><td>—</td><td>Colore di accento (<code>#rrggbb</code>).</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>appearance.zoom</code></td><td><code>number</code></td><td>—</td><td>Zoom dell&#39;interfaccia (0,5–3).</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>appearance.statusBar</code></td><td><code>boolean</code></td><td>—</td><td>Barra di stato compatta sotto l&#39;area dell&#39;editor (parole, caratteri, selezione, riga:colonna, modalità); spenta se non impostata (ADR-0035).</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>hotkeys</code></td><td><code>object</code></td><td>—</td><td>Scorciatoie predefinite: id del comando → combinazione. Si blocca una scorciatoia con <code>hotkeys.&lt;id comando&gt;</code>.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>sync.interval_seconds</code></td><td><code>integer</code></td><td><code>30</code></td><td>Intervallo di polling della sincronizzazione quando le notifiche push non sono disponibili (5–3600). Non bloccato sostituisce solo l&#39;intervallo automatico, la scelta dell&#39;utente resta.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>sync.max_file_size_bytes</code></td><td><code>integer</code></td><td><code>104857600</code></td><td>I file più grandi non si sincronizzano (il client li segnala). Il limite del server si imposta in <em>Limiti</em>.</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>attachments.max_size_bytes</code></td><td><code>integer</code></td><td>—</td><td>Riservato: nessun client lo applica ancora.</td><td>no</td><td>—</td></tr><tr><td><code>daily_notes.folder</code></td><td><code>string</code></td><td>—</td><td>Cartella delle note giornaliere.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>daily_notes.format</code></td><td><code>string</code></td><td>—</td><td>Formato della data nel nome della nota giornaliera.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>daily_notes.template</code></td><td><code>string</code></td><td>—</td><td>Modello della nota giornaliera.</td><td>sì</td><td>desktop, workbench web</td></tr><tr><td><code>templates.library_share_id</code></td><td><code>string</code></td><td>—</td><td>Condivisione montata in sola lettura come libreria di modelli del gruppo.</td><td>no</td><td>desktop, workbench web</td></tr><tr><td><code>servers</code></td><td><code>array</code></td><td>—</td><td>Elenco di server (<code>name</code>, <code>url</code>). Riservato: nessun client lo applica ancora.</td><td>no</td><td>—</td></tr><tr><td><code>auth.redirect_mode</code></td><td>enum: <code>auto</code>, <code>loopback</code>, <code>custom_scheme</code></td><td><code>&quot;auto&quot;</code></td><td>Redirect dell&#39;accesso desktop (D-08): loopback con ripiego sullo schema <code>clarae://</code> (<code>auto</code>), solo loopback, solo schema. Il workbench web usa la sessione della pagina.</td><td>no</td><td>desktop</td></tr><tr><td><code>security.vault_lock_minutes</code></td><td><code>integer</code></td><td>—</td><td>Minuti di inattività dopo i quali un vault privato sbloccato dimentica la chiave sul dispositivo (0 = mai, massimo 1440). Senza profilo vale la scelta dell&#39;utente, altrimenti 0.</td><td>sì</td><td>desktop, workbench web</td></tr></tbody></table><h3 id="applicazioni-note-per-chi-amministra" tabindex="-1">Applicazioni: note per chi amministra <a class="header-anchor" href="#applicazioni-note-per-chi-amministra" aria-label="Permalink to &quot;Applicazioni: note per chi amministra&quot;">​</a></h3><p><code>features.web_viewer</code> accende le <strong>applicazioni</strong>: pagine web registrate nel vault (file <code>.webapp</code>) che si aprono in una scheda. La guida per gli utenti è <a href="./../user-guide/applicazioni.html">Applicazioni</a>; la decisione e le sue ragioni sono in <a href="https://github.com/E2BRAdvisory/Clarae/blob/main/docs/adr/0056-applicazioni-in-vista-nativa.md" target="_blank" rel="noreferrer">ADR-0056</a>, accettato il 2026-11-15.</p><ul><li><strong>Acceso di default dalla 1.7.2</strong> (decisione dell&#39;owner, ADR-0060, accettata il 2026-11-16; fino alla 1.7.1 era spento). Chi non vuole le applicazioni le spegne con <code>{&quot;features&quot;: {&quot;web_viewer&quot;: false}}</code>, nel profilo globale o in uno di gruppo; il client lo legge con il profilo e, se lo si spegne, chiude le pagine aperte.</li><li><strong>Non c&#39;è un elenco di siti ammessi o vietati.</strong> Ogni utente decide quali indirizzi registrare. In un vault condiviso chi può scrivere può aggiungere un&#39;applicazione che gli altri vedranno: <strong>nessuna pagina si carica finché l&#39;utente non conferma l&#39;origine</strong>, la prima volta, su ogni dispositivo e per ogni vault.</li><li><strong>Che cosa può fare una pagina ospite.</strong> Gira in una vista separata dall&#39;app, <strong>senza alcun ponte verso l&#39;app</strong>: non può leggere le note né chiamare le funzioni dell&#39;app. Si aprono solo <code>http</code> e <code>https</code>, controllati a ogni spostamento; i download sono rifiutati; camera, microfono, posizione, notifiche e accesso ai file sono negati; non si apre alcuna finestra nell&#39;app (un indirizzo può andare al browser di sistema solo dopo un gesto dell&#39;utente nella pagina); un certificato non valido non si può aggirare; le richieste di credenziali del server (Basic, Digest, NTLM, certificato client) sono annullate, quindi <strong>l&#39;autenticazione HTTP di base non è supportata</strong> e un login con popup e <code>window.opener</code> non funziona. La CSP dell&#39;app non cambia e non si usano <code>&lt;iframe&gt;</code>.</li><li><strong>Rete privata.</strong> Un utente può registrare un indirizzo locale (<code>localhost</code>, un NAS, uno strumento self-hosted). Una pagina raggiunta da un sito pubblico non può portare la vista su un indirizzo locale: ci sono servizi del computer dell&#39;utente, compreso il listener di loopback dell&#39;accesso al cloud. <strong>Il controllo riguarda dove va la vista</strong>, non ciò che una pagina incorpora in un frame o richiede con <code>fetch</code>, e i nomi non vengono risolti: <strong>un nome che punta a un indirizzo locale (DNS rebinding) non è riconosciuto.</strong> Non è un sostituto di un firewall.</li><li><strong>Dove stanno i dati di sessione.</strong> Cookie, accessi e archivio locale delle pagine stanno <strong>sul dispositivo</strong>, su macOS in un archivio dati di WebKit per ogni vault; su Windows e su Linux in una cartella per vault sotto <code>webapps/</code> nella cartella dati dell&#39;app (persistente), con un identificatore casuale tenuto nel database locale dell&#39;app (<code>app.db</code>): non sono nel vault, <strong>non sono sincronizzati e non passano dal cloud</strong>, che non vede né registra nell&#39;audit le pagine aperte. Prima di macOS 14 l&#39;archivio non è persistente: la sessione dura quanto l&#39;app; su Windows e Linux lo è sempre.</li><li><strong>Come si cancellano.</strong> L&#39;utente: <em>Elimina i dati delle applicazioni</em> (palette), per il vault aperto e su quel dispositivo. L&#39;app: alla rimozione di una condivisione ricevuta cancella i dati di quel vault. <strong>Spegnere il flag non li cancella.</strong> Una cartella di vault eliminata fuori dall&#39;app non è nota all&#39;app subito: dalla 1.7.1 una <strong>pulizia in background</strong>, dopo l&#39;avvio, cancella i dati di un vault solo quando non esiste più con certezza. Il vault non è aperto, non è una condivisione ricevuta e non è tra i recenti, oppure vi è ma è stato aperto l&#39;ultima volta più di 30 giorni prima, <strong>non si trova su un volume rimovibile</strong> (un disco esterno, una condivisione di rete, <code>/Volumes</code>, <code>/media</code>, <code>/mnt</code> e simili), la cartella risponde «non esiste» (non «accesso negato») mentre quella che la contiene c&#39;è, si legge e <strong>non è vuota</strong> (una madre vuota è la firma di un punto di mount scelto dall&#39;utente e non montato, per esempio rclone, sshfs, macFUSE o Cryptomator: il vault si tiene). Limite noto: il dato di un vault cancellato che era l&#39;unica cosa nella sua cartella resta (qualche megabyte). Prima di cancellare l&#39;app ricontrolla che il vault non sia stato aperto nel frattempo. <strong>Mai</strong> per un vault solo chiuso, su un disco non montato o su una cartella che non si riesce a leggere: costa pochi megabyte tenere un archivio di troppo, e cancellare quello di un vault che esiste disconnette l&#39;utente dai siti. Non cancella nulla sul cloud.</li><li><strong>Tre sistemi, un ripiego (ADR-0062, accettata il 2026-11-20).</strong> La vista integrata c&#39;è sul desktop per <strong>macOS</strong> (WKWebView), <strong>Windows</strong> (WebView2) e <strong>Linux</strong> (WebKitGTK), accesa di default insieme al flag. <strong>Requisiti:</strong> Windows, <em>WebView2 Runtime</em> dalla versione <strong>1.0.2210.55</strong>; Linux, <strong><code>webkit2gtk-4.1</code> dalla versione 2.40</strong>, il pacchetto ufficiale, costruito per GTK 3 (una build per GTK 4 o senza cgo non ha il driver) e <strong>bubblewrap (<code>bwrap</code>) funzionante</strong>: la sandbox di WebKit è obbligatoria e il driver non crea una vista senza. <strong>Se il requisito manca</strong> (runtime assente o troppo vecchio, <code>bwrap</code> assente, sandbox non creabile, finestra con una struttura inattesa) l&#39;utente non vede un errore: la scheda mostra «Apri nel browser» e, se non si era ancora aperta nessuna pagina in quella sessione, lo fa per tutta la sessione. <strong>Windows e Linux sono stati provati su una finestra reale dall&#39;owner il 27 novembre 2026</strong> (matrice <a href="https://github.com/E2BRAdvisory/Clarae/blob/main/docs/qa/m18-webview-matrice.md" target="_blank" rel="noreferrer"><code>m18-webview-matrice.md</code></a>, esito positivo dichiarato, senza esito per riga). Se un difetto compare, chi amministra può spegnere il flag <code>features.web_viewer</code> dal profilo (per tutti) oppure, <strong>su un singolo computer Windows o Linux</strong>, avviare il client con la variabile d&#39;ambiente <strong><code>CLARAE_WEBVIEW=off</code></strong>: vale solo il valore <code>off</code> (maiuscole e spazi ai lati non contano), si legge all&#39;avvio e <strong>macOS non la legge</strong>. La variabile <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code> (1.7.1) non esiste più e non ha effetto.</li><li><strong>Linux: sandbox e ambienti.</strong> Il driver non parte, e vale il ripiego, se <code>bwrap</code> non è nel <code>PATH</code>, se una sonda di avvio (che replica gli argomenti con cui WebKit lancia <code>bwrap</code>) fallisce, o se nell&#39;ambiente c&#39;è <code>WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS</code> (WebKit spegnerebbe la sandbox per tutto il processo: il driver preferisce non mostrare la pagina). Tipicamente è il caso di un <strong>container</strong> senza privilegi o di un sistema con i namespace utente spenti. <strong>Rischio residuo:</strong> se il processo web non parte dopo una sonda riuscita, WebKit abortisce l&#39;app (nessun ripiego). <strong>Flatpak e Snap non sono pacchetti distribuiti né supportati</strong> (decisione dell&#39;owner, 2026-11-27): i pacchetti sono <code>.deb</code> e AppImage.</li><li><strong>Differenze su Linux.</strong> Il selettore di file della pagina è annullato; il driver non conosce con certezza il frame di una navigazione e per ciò che non è <code>about:</code>, <code>blob:</code> o <code>data:</code> applica le regole del frame principale, che sono le più severe (un iframe verso un indirizzo locale da una pagina pubblica è rifiutato, e così un redirect verso un indirizzo locale dopo una navigazione verso un host pubblico).</li><li><strong>Limiti di risorse.</strong> Al massimo 32 pagine aperte per vault e 64 in tutto: ciascuna è un processo del sistema. Lavorare in una pagina conta come attività per il blocco automatico dei vault privati; il blocco chiude le pagine.</li></ul><h3 id="terminale-integrato-nessun-flag" tabindex="-1">Terminale integrato: nessun flag <a class="header-anchor" href="#terminale-integrato-nessun-flag" aria-label="Permalink to &quot;Terminale integrato: nessun flag&quot;">​</a></h3><p>Il client desktop ha un <strong>terminale integrato</strong> (<a href="https://github.com/E2BRAdvisory/Clarae/blob/main/docs/adr/0064-terminale-integrato-e-finestra-separata.md" target="_blank" rel="noreferrer">ADR-0064</a>, accettata il 2026-11-20; guida: <a href="./../user-guide/terminale.html">Terminale</a>). <strong>Non si spegne dal profilo:</strong> non esiste una chiave <code>features.terminal</code> (lo schema del Config Profile non la contiene) e il profilo non lo influenza. È una decisione dell&#39;owner; se servirà un flag sarà un nuovo ADR. Da sapere:</p><ul><li>Il terminale esegue <strong>qualunque comando dell&#39;utente con i suoi permessi</strong> e <strong>non è un confine di sicurezza</strong>: una shell può leggere e scrivere ovunque l&#39;utente possa, anche fuori dalle regole dell&#39;app (altri vault, <code>.clarae/</code>, mount in sola lettura aperti come cartella). I permessi di condivisione restano imposti dal cloud e dall&#39;app, non dal terminale.</li><li>Una shell parte <strong>solo da un gesto dell&#39;utente</strong>, mai da un file del vault, da un link o da un deep link <code>clarae://</code>.</li><li>Per un vault in sola lettura per l&#39;utente (condivisione come lettore, o revocata) il terminale non si apre e le shell già aperte in quel vault si chiudono.</li><li>Non c&#39;è nel workbench web. Il cloud non vede né registra nell&#39;audit l&#39;uso del terminale.</li><li>Su un computer gestito, chi vuole impedirlo deve farlo con i mezzi del sistema operativo (criteri di esecuzione, AppLocker, profili di gestione dei dispositivi).</li></ul><h2 id="quote-e-limiti" tabindex="-1">Quote e limiti <a class="header-anchor" href="#quote-e-limiti" aria-label="Permalink to &quot;Quote e limiti&quot;">​</a></h2><p><em>Amministrazione → Limiti</em> (impostazioni runtime, senza riavvio):</p><table tabindex="0"><thead><tr><th>Impostazione</th><th>Significato</th></tr></thead><tbody><tr><td>Quota predefinita</td><td>Spazio per utente se non c&#39;è un override personale.</td></tr><tr><td>Soglie di avviso / critica</td><td>Percentuali (<code>warn_percent</code> &lt; <code>critical_percent</code>) che colorano le barre di utilizzo.</td></tr><tr><td>Conservazione storico</td><td>Giorni di tutte le revisioni (<code>history.retention_days</code>) e giorni di una revisione al giorno.</td></tr><tr><td>Dimensione massima file</td><td>Oltre il limite il file non si sincronizza (errore chiaro al client).</td></tr></tbody></table><p>Regole da conoscere: la quota conta <strong>solo i file correnti</strong>, non lo storico (D-03); i vault <strong>condivisi</strong> consumano la quota del proprietario, anche se a scrivere è un altro utente; un valore <code>-1</code> significa &quot;illimitato&quot;. Per cambiare la quota di un utente: <em>Utenti → utente → Cambia quota…</em>; per più utenti selezionarli nella lista e usare la quota in blocco. <em>Amministrazione → Archiviazione</em> mostra l&#39;utilizzo totale, la tendenza giornaliera e i principali consumatori.</p><h2 id="sospensione-ruoli-eliminazione" tabindex="-1">Sospensione, ruoli, eliminazione <a class="header-anchor" href="#sospensione-ruoli-eliminazione" aria-label="Permalink to &quot;Sospensione, ruoli, eliminazione&quot;">​</a></h2><p>Dalla pagina dell&#39;utente: sospendi/riattiva (effetto entro 30 s), cambia ruolo, reimposta password (via Keycloak), elimina. Non si può sospendere, degradare o eliminare l&#39;ultimo amministratore attivo né se stessi; il controllo è serializzato, quindi vale anche per due amministratori che agiscono contemporaneamente.</p><p>Il <strong>cambio di ruolo</strong> vale dalla richiesta successiva, anche per i token emessi prima (il database prevale su di essi, ADR-0041; dettagli in <a href="./keycloak.html#ruoli-di-realm">Keycloak</a>) e richiede l&#39;Admin API di Keycloak configurata.</p><p>L&#39;<strong>eliminazione</strong> dalla console è la stessa operazione della cancellazione dell&#39;account fatta dall&#39;utente (ADR-0021, ADR-0041): l&#39;account è anonimizzato subito (nome, e-mail, dispositivi, indirizzi IP nell&#39;audit), i suoi vault entrano nel periodo di conservazione (<code>privacy.account_purge_days</code>, default 30 giorni) prima del purge definitivo, appartenenze ai gruppi, grant ricevuti, upload in corso ed export pronti sono rimossi. I grant che l&#39;utente aveva concesso come <em>manager</em> su vault di altri proprietari <strong>restano validi</strong>: il proprietario del vault ne diventa il concedente (azione di audit <code>share.grants_reattributed</code>, una per condivisione) e i destinatari non perdono l&#39;accesso.</p><h2 id="registro-di-audit" tabindex="-1">Registro di audit <a class="header-anchor" href="#registro-di-audit" aria-label="Permalink to &quot;Registro di audit&quot;">​</a></h2><p><em>Amministrazione → Audit</em> elenca le azioni amministrative e di condivisione con data, attore, IP, bersaglio e dettagli; è filtrabile per attore, azione e periodo, paginato con cursore ed esportabile in <strong>CSV</strong>. Azioni registrate:</p><table tabindex="0"><thead><tr><th>Area</th><th>Azioni</th></tr></thead><tbody><tr><td>Utenti</td><td><code>user.create</code>, <code>user.update</code>, <code>user.delete</code>, <code>user.suspend</code>, <code>user.activate</code>, <code>user.quota</code>, <code>user.role</code>, <code>user.reset_password</code></td></tr><tr><td>Gruppi</td><td><code>group.create</code>, <code>group.update</code>, <code>group.delete</code></td></tr><tr><td>Condivisioni</td><td><code>share.create</code>, <code>share.update</code>, <code>share.revoke</code>, <code>share.accept</code>, <code>share.decline</code>, <code>share.grants_reattributed</code></td></tr><tr><td>Export</td><td><code>vault.export</code>, <code>vault.zip</code></td></tr></tbody></table><p>Il registro non contiene contenuti di note, nomi di file né segreti. Le voci non si modificano dall&#39;interfaccia. Una politica di conservazione dell&#39;audit non è configurabile in questa versione: pianificare l&#39;archiviazione esterna (CSV periodico o dump della tabella) se richiesto da normative.</p>',31)])])}const m=o(d,[["render",n]]);export{g as __pageData,m as default};
